-- Business accounts: the demo businesses from src/data/business.ts as business accounts.
--
-- Generated by supabase/generators/import_groups.py from src/data/business.ts (via
-- supabase/generators/export_demo_groups.ts). Edit the generator, not this file.
--
-- Owner decisions, 15 Sep 2026: MusicLinkd has account kinds: talent (a human) and business (every
-- other account). A business is an account like talent (a profile with a sign-in-less auth.users row, as in
-- 20260914150000_import_profiles.sql), its username in the same namespace; it is a business because it
-- has a profile_business row. The 20 Firebase businesses (19 BUSINESS, 1 VENUE) already have theirs
-- (20260914170000_profile_sections.sql); every business screen reads these tables.
--
-- Schema, for fields the demo business has and the tables did not:
--   profile_business + founded_year
--   profile_members  + photo_url, since_year, status ('active' | 'invited')
--   studio_rooms     + kind, photo_url, gear (free text; amenities stay taxonomy slugs)
--
-- Data: 1 business account (soundhouse.bandra), with its business details, 3 gallery photos,
-- 3 services, 3 team members, 1 studio with 2 rooms, 2 reviews and 3 credits
-- (portfolio_items, kind 'credit').
-- Not stored (no column, or not a fact): followers and bookings counts, contact phone (masked in the
-- demo), email and website, review author photos and dates, the owner's personal username.
-- The migration refuses a reserved or taken username and a business type missing from the taxonomy.
--
-- Each data block re-reads what it wrote and raises on any difference. Idempotent: fixed uuid5 ids.
-- Rollback: DELETE FROM auth.users WHERE id IN ('e824d804-bcf6-52e2-a961-bbe37b909385'); (profile rows
-- cascade), then drop the added columns.

ALTER TABLE public.profile_business
  ADD COLUMN IF NOT EXISTS founded_year int CHECK (founded_year BETWEEN 1800 AND 2100);

ALTER TABLE public.profile_members
  ADD COLUMN IF NOT EXISTS photo_url text,
  ADD COLUMN IF NOT EXISTS since_year int CHECK (since_year BETWEEN 1800 AND 2100),
  ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'invited'));

ALTER TABLE public.studio_rooms
  ADD COLUMN IF NOT EXISTS kind text,
  ADD COLUMN IF NOT EXISTS photo_url text,
  ADD COLUMN IF NOT EXISTS gear text[] NOT NULL DEFAULT '{}';

-- business accounts: auth users and profiles (1 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"id":"e824d804-bcf6-52e2-a961-bbe37b909385","username":"soundhouse.bandra","display_name":"Soundhouse Bandra","headline":"Two rooms, one tape machine, no clock-watching.","bio":"A Bandra-based recording studio built for bands and singer-songwriters. Live room fits an eight-piece, control room runs a hybrid analogue chain, and the house engineers know how to keep a take alive.","city":"Mumbai","roles":["studio"],"avatar_url":"https://images.unsplash.com/photo-1598488035139-bdbb2231ce04?auto=format&fit=crop&w=200&q=80","cover_url":"https://images.unsplash.com/photo-1519508234439-4f23643125c1?auto=format&fit=crop&w=800&q=80","visibility":"public","is_verified":true}]$json$;
BEGIN
  -- A business username is in the same namespace as talent's: refuse a reserved or taken name, and
  -- a business type the taxonomy does not have.
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, roles text[], avatar_url text, cover_url text, visibility text, is_verified boolean) JOIN public.reserved_usernames x ON x.name = r.username) THEN
    RAISE EXCEPTION 'business accounts: a username is reserved';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, roles text[], avatar_url text, cover_url text, visibility text, is_verified boolean) JOIN public.profiles p
             ON lower(p.username) = lower(r.username) AND p.id <> r.id) THEN
    RAISE EXCEPTION 'business accounts: a username is already taken by another profile';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, roles text[], avatar_url text, cover_url text, visibility text, is_verified boolean), unnest(r.roles) AS x(slug)
             WHERE NOT EXISTS (SELECT 1 FROM public.taxonomy_options o
                               WHERE o.category_key = 'person_types' AND o.slug = x.slug)) THEN
    RAISE EXCEPTION 'business accounts: a business type has no person_types option';
  END IF;

  INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, raw_app_meta_data,
    raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new,
    email_change, is_sso_user, is_anonymous)
  SELECT '00000000-0000-0000-0000-000000000000', r.id, 'authenticated', 'authenticated', NULL, NULL, '{}'::jsonb,
    jsonb_build_object('full_name', r.display_name, 'avatar_url', r.avatar_url), now(), now(), '', '', '', '', false, false
  FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, roles text[], avatar_url text, cover_url text, visibility text, is_verified boolean)
  ON CONFLICT (id) DO NOTHING;

  -- on_auth_user_created has made a bare profile for each; fill it.
  INSERT INTO public.profiles (id, username, display_name, headline, bio, city, roles, avatar_url, cover_url, visibility, is_verified, onboarding_complete)
  SELECT r.id, r.username, r.display_name, r.headline, r.bio, r.city, r.roles, r.avatar_url, r.cover_url, r.visibility, r.is_verified, true
  FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, roles text[], avatar_url text, cover_url text, visibility text, is_verified boolean)
  ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username, display_name = EXCLUDED.display_name, headline = EXCLUDED.headline, bio = EXCLUDED.bio, city = EXCLUDED.city, roles = EXCLUDED.roles, avatar_url = EXCLUDED.avatar_url, cover_url = EXCLUDED.cover_url, visibility = EXCLUDED.visibility, is_verified = EXCLUDED.is_verified,
    onboarding_complete = true;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, username text, display_name text, headline text, bio text, city text, roles text[], avatar_url text, cover_url text, visibility text, is_verified boolean) JOIN public.profiles t ON t.id = r.id
      WHERE (t.id, t.username, t.display_name, t.headline, t.bio, t.city, t.roles, t.avatar_url, t.cover_url, t.visibility, t.is_verified) IS NOT DISTINCT FROM (r.id, r.username, r.display_name, r.headline, r.bio, r.city, r.roles, r.avatar_url, r.cover_url, r.visibility, r.is_verified))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'business accounts: stored profiles differ from the payload';
  END IF;
END
$import$;

