  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, user_id uuid, title text, kind text, role text, release_year int, published boolean, sort_order int) JOIN public.portfolio_items t ON t.id = r.id
      WHERE (t.id, t.user_id, t.title, t.kind, t.role, t.release_year, t.published, t.sort_order) IS NOT DISTINCT FROM (r.id, r.user_id, r.title, r.kind, r.role, r.release_year, r.published, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'portfolio_items import: stored rows differ from the payload';
  END IF;
END
$import$;
